// Incremental mode, step 2: what a blind search costs at each wait (engine/searchCost.js), over several random
// orders. npm run search-cost [seeds] → .cache/search-cost.md (a few minutes; a measurement, not a generated file).
import fs from 'node:fs';
import path from 'node:path';
import { loadCase } from '../engine/loadCase.js';
import { searchCost } from '../engine/searchCost.js';
import { make } from '../engine/minimalTable.js';

const dir = path.join(path.dirname(new URL(import.meta.url).pathname), '../cases/silver-blaze');
const model = await loadCase(dir);
const read = (f) => JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8'));
const seeds = +(process.argv[2] ?? 3);
const runs = [];
for (let s = 1; s <= seeds; s++) { runs.push(searchCost(model, read('hints.json'), read('incremental.json'), make, { seed: s })); console.error(`seed ${s}: ${runs.at(-1).score}`); }
const n = (x) => (x === null || x === undefined ? '–' : Math.round(x).toLocaleString('en-US'));
const mean = (xs) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null);
const L = [];
L.push(`# Blind search cost (${seeds} random orders)`, '', 'Generated by `npm run search-cost` (engine/searchCost.js); a measurement.', '');
L.push(`Score: ${runs.map((x) => x.score).join(', ')}. Clashes at the end: ${runs.map((x) => x.extra.clashes).join(', ')}. Waits no search met: ${runs.map((x) => x.extra.fallback.length).join(', ')}.`, '');
L.push(`Unreachable in the page: ${JSON.stringify(runs[0].extra.unreachable)}.`, '');
L.push(`Inferences built that the minimal playthrough does not: ${mean(runs.map((x) => x.extra.builtNotNeeded.length))} on average (${runs[0].extra.builtNotNeeded.join(', ')}).`, '');
L.push('## Each wait', '', '| ¶ | Wait | Family | Space | Solutions | Checks (run: mean, min–max; counted: expected) | Answers route (expected) |', '|---:|---|---|---:|---:|---:|---:|');
const keys = [...new Set(runs.flatMap((x) => x.rows.map((r) => `${r.para}|${r.wait}`)))].sort((a, b) => parseInt(a, 10) - parseInt(b, 10));
const byFam = {};
for (const k of keys) {
    const rs = runs.map((x) => x.rows.find((r) => `${r.para}|${r.wait}` === k)).filter(Boolean);
    const r0 = rs[0];
    const live = rs.filter((r) => !r.already);
    let cost = 'made already';
    if (live.length) {
        const vals = live.map((r) => r.checks ?? r.expected).filter((v) => v !== null && v !== undefined);
        cost = vals.length ? (live[0].checks !== undefined ? `${n(mean(vals))} (${n(Math.min(...vals))}–${n(Math.max(...vals))})` : n(mean(vals))) : 'not offered';
        (byFam[r0.family] ??= []).push(mean(vals) ?? 0);
    }
    const space = r0.space ?? (r0.targets ? `${n(r0.targets)} × ${n(r0.reasons)}` : '');
    const sol = r0.solutions ?? r0.holding ?? '';
    const ans = r0.answers ? (r0.answers.provable ? `${n(r0.answers.expected)}${r0.answers.page ? '' : ' (not in the page)'}` : 'not provable yet') : '';
    L.push(`| ${r0.para} | ${r0.wait} | ${r0.family} | ${typeof space === 'number' ? n(space) : space} | ${sol} | ${cost} | ${ans} |`);
}
L.push('', '## By family', '', '| Family | Waits searched | Checks in all (mean) | Largest |', '|---|---:|---:|---:|');
for (const [f, xs] of Object.entries(byFam)) L.push(`| ${f} | ${xs.length} | ${n(xs.reduce((a, b) => a + b, 0))} | ${n(Math.max(...xs))} |`);
L.push('', '## The stops', '', '| ¶ | Cards | Answers | Seals | Absences | Drop targets × reasons | Spans collected | Asked | Stale negatives |', '|---:|---:|---:|---:|---:|---:|---:|---:|---:|');
for (const s of runs[0].stops) L.push(`| ${s.para} | ${n(s.cards)} | ${n(s.answers)} | ${n(s.sealSpace)} | ${n(s.absenceSpace)} | ${n(s.dropTargets)} × ${n(s.dropReasons)} | ${s.collect} | ${s.ask} | ${s.stale} |`);
fs.mkdirSync(path.join(dir, '../../.cache'), { recursive: true });
fs.writeFileSync(path.join(dir, '../../.cache/search-cost.md'), `${L.join('\n')}\n`);
console.log('wrote .cache/search-cost.md');
